package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectionType_construct_TriageGen1Test {

    @Test
    public void testConstruct_WithListAndInteger() {
        // Arrange
        Class<?> rawType = List.class;
        JavaType elemT = TypeFactory.defaultInstance().constructType(Integer.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull("Resulting CollectionType should not be null", result);
        assertEquals("Raw type should match the input", rawType, result.getRawClass());
        assertEquals("Element type should match the input", elemT, result.getContentType());

        // Verify internal structure via toString or other accessible properties if possible
        // Since we are testing the factory method specifically:
        String expectedString = "java.util.List<java.lang.Integer>";
        assertEquals("toString should reflect the constructed type", expectedString, result.toString());
    }








}

