package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectionType_construct_TriageGen1Test {





    @Test
    public void testConstruct_WithComplexType() {
        // Arrange
        Class<?> rawType = List.class;
        // Construct a nested type: List<List<String>>
        JavaType innerElemT = TypeFactory.defaultInstance().constructType(String.class);
        JavaType outerElemT = TypeFactory.defaultInstance().constructCollectionType(List.class, innerElemT);

        // Act
        CollectionType result = CollectionType.construct(rawType, outerElemT);

        // Assert
        assertNotNull(result);
        assertEquals(List.class, result.getRawClass());
        assertEquals(outerElemT, result.getContentType());
        assertEquals("java.util.List<java.util.List<java.lang.String>>", result.toString());
    }




}

